head.script:
scwin.init = function() {
    var data1 = [];
    var data2 = [];
    var data3 = [];
    var row = 10;
    var col = 3;
    for (var i = 0; i < row; i++) {
        for (var j = 0; j < col; j++) {
            if (j === 0) {
                data1.push("label=" + String(i));
                data2.push("L=" + String(i));
                data3.push("_L_:" + String(i));
            } else if (j === 1) {
                data1.push("value=" + String(i));
                data2.push("V=" + String(i));
                data3.push("_V_:" + String(i));
            } else {
                data1.push("dummy=" + String(i));
                data2.push("D=" + String(i));
                data3.push("_d_:" + String(i));
            }
        }
    }
    dataList1.setData(data1);
    dataList2.setData(data2);
    dataList3.setData(data3);
};
scwin.onpageunload = function() {};
scwin.trigger2_onclick = function(e) {
    var obj = {
        "nodeset": "data:dataList3",
        "label": "col1",
        "value": "col2",
        "width": 400,
        "height": 300,
        "visibleRowNum": 10,
        "item": [{
            "ref": "col1",
            "header": "NLabel"
        }, {
            "ref": "col2",
            "header": "NValue"
        }, {
            "ref": "col3",
            "header": "NDummy"
        }]
    };
    selectbox1.setGridItemset(obj);
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //pc
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'autoComplete1_label').innerText == 'L=0'", "true");
    //WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'selectbox1_label').innerText == '_L_:0'", "true");
    //WebSquare.wUnit.addCommand("pause", "500");
    //mobile
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('autoComplete1').getValue() == 'V=0'", "true");
    //WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('selectbox1').getValue() == '_V_:0'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {
	scwin.init();
}
